eck(session.castSpell(hero->handle,flak),"Gyrocopter second Flak Cannon rejected");for(int i=0;i<20 && !hero->abilities.contains(ObjectData::code("A1TW"));++i)session.advance(.25);check(hero->abilities.contains(ObjectData::code("A1TW")),"Gyrocopter second barrage missing");primary=number(victim->life);extra=number(second->life);check(session.attackUnit(hero->handle,victim->handle),"Gyrocopter cancel attack rejected");for(int i=0;i<80 && !hero->combat.windup;++i)session.advance(.03125);check(hero->combat.windup && hero->combat.windup->barrage==ObjectData::code("A1TW"),"Gyrocopter barrage windup missing");call("IssueImmediateOrder",{self,vm.string("stop")});for(int i=0;i<64;++i)session.advance(.03125);expectNear(number(victim->life),primary,"Canceled Gyrocopter attack hit its target");expectNear(number(second->life),extra,"Canceled Gyrocopter attack launched barrage");check(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS DotA Gyrocopter four attacks and expiry\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return;
