Near(number(victim->life),number(second->life),"Gyrocopter fired again after stopping");expectNear(number(ally->life),5000,"Gyrocopter barrage hit an ally");expectNear(number(outside->life),5000,"Gyrocopter barrage hit an out-of-range enemy");for(int i=0;i<80;++i)session.advance(.25);check(session.units().contains(hero->handle) && hero->type==heroType && hero->heroAttributes==attributes && hero->experience==experience && hero->level==level && !hero->abilities.contains(ObjectData::code("A1TW")) && !GetModuleHandleW(L"Game.dll"),"Gyrocopter barrage did not expire and restore its original form");std::cout<<"PASS DotA Gyrocopter Flak Cannon grants source barrage\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return;
